// Changes: Create an IR slot with the ID used by semantic analysis.
static void add_local_slot(Ctx* ctx, IrFunctionId function_id, AstNode* ident) {
  const SymtableData* symbol = ast_node_get_symbol(ident);
  const char* name = ast_node_get_name(ident);

  IrStackSlotId slot = ir_add_slot(ctx, function_id, name, symbol->ir_type);
  if (slot != symbol->ir_index)
    THROW(E_INTERNAL_ERROR, "Unexpected slot ID for '%s'", name);
}

