// Changes: Register source slots before lowering any function instructions.
void lower_local_slots(Ctx* ctx, IrFunctionId function_id, AstNode* node) {
  AstNodeType kind = ast_node_get_type(node);
  size_t count = ast_node_get_child_count(node);

  // A for loop declares its iterator after its range and checks its guards
  // before its body. Follow that order to keep the semantic slot IDs.
  if (kind == AST_NODE_FOR) {
    lower_local_slots(ctx, function_id,
                      ast_node_child(ctx, node, AST_FOR_SOURCE));
    add_local_slot(ctx, function_id, ast_node_child(ctx, node, AST_FOR_IDENT));

    for (size_t i = AST_FOR_FIRST_GUARD; i < count; i++)
      lower_local_slots(ctx, function_id, ast_node_child(ctx, node, i));

    lower_local_slots(ctx, function_id,
                      ast_node_child(ctx, node, AST_FOR_BODY));
    return;
  }

  for (size_t i = 0; i < count; i++)
    lower_local_slots(ctx, function_id, ast_node_child(ctx, node, i));

  // An initializer can contain declarations of its own.
  if (kind == AST_NODE_VAL || kind == AST_NODE_VAR)
    add_local_slot(ctx, function_id, ast_node_child(ctx, node, AST_VAL_IDENT));
}

