// Changes: Lower an initializer or assignment and store its value.
static IrOperand lower_store(Ctx* ctx,
                             IrFunctionId function_id,
                             IrBlockId* block_id,
                             AstNode* node) {
  bool assignment = ast_node_get_type(node) == AST_NODE_ASSIGN;
  AstNode* ident =
      ast_node_child(ctx, node, assignment ? AST_ASSIGN_IDENT : AST_VAL_IDENT);
  AstNode* value_node =
      ast_node_child(ctx, node, assignment ? AST_ASSIGN_VALUE : AST_VAL_INIT);

  IrOperand value = lower_expression(ctx, function_id, block_id, value_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  const SymtableData* symbol = ast_node_get_symbol(ident);
  ir_add_instruction(
      ctx, function_id, *block_id,
      (IrInstruction){
          .type = IR_INST_STORE,
          .operands.store = {.source = value, .target = symbol->ir_index}});

  return unit_operand();
}

