// Changes: Evaluate an explicit return and close the current block.
static IrOperand lower_return(Ctx* ctx,
                              IrFunctionId function_id,
                              IrBlockId* block_id,
                              AstNode* node) {
  AstNode* value_node = ast_node_child(ctx, node, AST_RETURN_VALUE);
  IrOperand value = unit_operand();

  // A Unit function still evaluates the expression for its side effects.
  if (ast_node_get_type(value_node) != AST_NODE_NONE)
    value = lower_expression(ctx, function_id, block_id, value_node);

  if (*block_id != IR_INVALID_ID) {
    emit_return(ctx, function_id, *block_id, value);
    *block_id = IR_INVALID_ID;
  }

  return unit_operand();
}

