// Changes: Lower a block in source order and retain its last value.
static IrOperand lower_block(Ctx* ctx,
                             IrFunctionId function_id,
                             IrBlockId* block_id,
                             AstNode* node) {
  IrOperand value = unit_operand();
  size_t count = ast_node_get_child_count(node);

  // A return ends this path. Local slots have already been registered.
  for (size_t i = 0; i < count && *block_id != IR_INVALID_ID; i++) {
    AstNode* statement = ast_node_child(ctx, node, i);
    value = lower_statement(ctx, function_id, block_id, statement);
  }

  return value;
}

