// Changes: Dispatch blocks, stores, explicit returns, and expression
// statements.
IrOperand lower_statement(Ctx* ctx,
                          IrFunctionId function_id,
                          IrBlockId* block_id,
                          AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_BLOCK:
      return lower_block(ctx, function_id, block_id, node);

    case AST_NODE_VAL:
    case AST_NODE_VAR:
    case AST_NODE_ASSIGN:
      return lower_store(ctx, function_id, block_id, node);

    case AST_NODE_RETURN:
      return lower_return(ctx, function_id, block_id, node);

    default:
      return lower_expression(ctx, function_id, block_id, node);
  }
}
